for task in tasks:
    while not task.done():
        try:
            await asyncio.shield(task)
        except asyncio.CancelledError:
            # Either ``task`` finished by being cancelled (fine) or *we*
            # were cancelled again while waiting.  Distinguish the two: if
            # the child is done, move on; otherwise keep waiting so its
            # cleanup can run to completion.
            if task.done():
                break
            continue
        except Exception:
            # The child raised a real error during its work/cleanup; it is
            # done as far as we are concerned.
            break

