while True:
    pending = [task for task in tasks if not task.done()]
    if not pending:
        return
    try:
        # ``asyncio.wait`` waits on the children without ever cancelling
        # them.  If a fresh ``CancelledError`` is thrown into *our* frame we
        # simply loop again, so the children keep running their cleanup
        # until they are all done.
        await asyncio.wait(pending)
    except asyncio.CancelledError:
        continue

